// Checks the X-LendLoop-Signature header Convex put on this request.
// Same algorithm as verifyRequest in convex/lib/signature.ts:
//   header "t=<unix>,v1=<hex>", |now - t| <= 300 s,
//   v1 == HMAC-SHA256(CONVEX_TO_N8N_SECRET, `${t}.POST./webhook/lendloop-loan-events.${rawBody}`)
const crypto = require('crypto');
const TOLERANCE_SECONDS = 300;
const PATH = '/webhook/lendloop-loan-events';

function verify(secret, method, path, rawBody, header) {
  if (!header) return { ok: false, reason: 'missing' };
  const m = /^t=(\d{1,12}),v1=([0-9a-f]{64})$/.exec(header.trim());
  if (!m) return { ok: false, reason: 'malformed' };
  const t = Number(m[1]);
  if (Math.abs(Math.floor(Date.now() / 1000) - t) > TOLERANCE_SECONDS) return { ok: false, reason: 'stale' };
  const expected = crypto.createHmac('sha256', secret).update(`${t}.${method}.${path}.${rawBody}`, 'utf8').digest();
  // Constant-time comparison; both sides are 32 bytes.
  return crypto.timingSafeEqual(expected, Buffer.from(m[2], 'hex')) ? { ok: true } : { ok: false, reason: 'mismatch' };
}

// The Webhook node ("Raw Body" on) keeps the exact bytes it received in binary property "data".
const input = $input.first();
const rawBody = input.binary?.data ? (await this.helpers.getBinaryDataBuffer(0, 'data')).toString('utf8') : '';
const result = verify($env.CONVEX_TO_N8N_SECRET, 'POST', PATH, rawBody, input.json.headers['x-lendloop-signature']);

// Parse only once the signature checks out. Later nodes read the event from here.
return [{ json: result.ok ? { ok: true, event: JSON.parse(rawBody) } : { ok: false, reason: result.reason } }];

// --- sign: identical in every LendLoop workflow ---
// Same algorithm as signRequest in convex/lib/signature.ts:
//   X-LendLoop-Signature: t=<unix seconds>,v1=HMAC-SHA256(secret, `${t}.${METHOD}.${path}.${body}`)
// The HTTP Request node sends `rawBody` as a raw string, so the signed bytes are the sent bytes.
const crypto = require('crypto');
function sign(method, path, body) {
  const t = Math.floor(Date.now() / 1000);
  const v1 = crypto
    .createHmac('sha256', $env.N8N_TO_CONVEX_SECRET)
    .update(`${t}.${method}.${path}.${body}`, 'utf8')
    .digest('hex');
  const base = $env.LENDLOOP_CONVEX_SITE_URL.replace(/\/$/, '');
  return { url: base + path, signature: `t=${t},v1=${v1}`, rawBody: body };
}
// --- end sign ---

// Ask Convex for the right to send this event's email (a 5-minute lease). Convex answers
// proceed: false if the event was already notified or another run holds the lease.
const { eventId } = $('Verify signature').first().json.event;
return [{ json: sign('POST', '/automation/notifications/claim', JSON.stringify({ eventId })) }];

// Everything a user typed (names, tool names) goes through escapeHtml before it reaches
// the HTML, so a tool called "<b>Drill</b> & Saw" shows up literally.
const escapeHtml = (s) =>
  String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c]);

// "2026-11-12" -> "Thu, 12 Nov 2026". Loan dates are UTC calendar dates.
const formatDate = (d) =>
  new Date(`${d}T00:00:00Z`).toLocaleDateString('en-GB', { timeZone: 'UTC', weekday: 'short', day: 'numeric', month: 'short', year: 'numeric' });

// One plain layout for every LendLoop email. All arguments are plain text; this escapes them.
function layout({ greetingName, line, detail, link, cta }) {
  return [
    '<div style="font-family:system-ui,-apple-system,sans-serif;max-width:480px;margin:0 auto;color:#18181b;line-height:1.5">',
    `<p>Hi ${escapeHtml(greetingName)},</p>`,
    `<p>${escapeHtml(line)}</p>`,
    `<p style="padding:12px 16px;background:#f4f4f5;border-radius:8px">${detail.map(escapeHtml).join('<br>')}</p>`,
    `<p><a href="${escapeHtml(link)}" style="display:inline-block;padding:10px 16px;background:#18181b;color:#fff;border-radius:6px;text-decoration:none">${escapeHtml(cta)}</a></p>`,
    '<p style="color:#71717a;font-size:12px">You get this email because you use LendLoop.</p>',
    '</div>',
  ].join('\n');
}

// Builds the email for one loan event. The recipient comes from the
// payload; Convex already picked lender or borrower.
const e = $('Verify signature').first().json.event;
const tool = e.tool.name;
const actor = e.actor?.name;
// Convex names the system "LendLoop" when nobody acted (auto-decline, listing removed).
const bySystem = !actor; // Convex sends actor: null when the system acted

// One entry per event type: subject, the sentence that says what happened, the button label.
const templates = {
  'loan.requested': {
    subject: `New request to borrow your ${tool}`,
    line: `${actor} would like to borrow your ${tool}.`,
    cta: 'Review the request',
  },
  'loan.approved': {
    subject: `Approved: you can borrow ${tool}`,
    line: `${actor} approved your request to borrow ${tool}. The loan page shows their email so you can arrange pickup.`,
    cta: 'Open the loan',
  },
  'loan.declined': {
    subject: `Request declined: ${tool}`,
    line: bySystem
      ? `Your request to borrow ${tool} was declined because another request for those dates was approved.`
      : `${actor} declined your request to borrow ${tool}.`,
    cta: 'Open the request',
  },
  'loan.cancelled': {
    subject: `Request cancelled: ${tool}`,
    line: bySystem
      ? `The request to borrow ${tool} was cancelled because the listing is no longer available.`
      : `${actor} cancelled the request to borrow ${tool}.`,
    cta: 'Open the request',
  },
  'loan.return_claimed': {
    subject: `Please confirm the return of your ${tool}`,
    line: `${actor} says they returned your ${tool}. Please confirm the return, or dispute it if you have not got it back.`,
    cta: 'Confirm or dispute',
  },
  'loan.returned': {
    subject: `Return confirmed: ${tool}`,
    line: `${actor} confirmed that ${tool} is back. Thanks for returning it!`,
    cta: 'Open the loan',
  },
  'loan.return_disputed': {
    subject: `Return disputed: ${tool}`,
    line: `${actor} says ${tool} has not come back yet, so the loan is still open. Please get in touch with them.`,
    cta: 'Open the loan',
  },
};

const t = templates[e.type];
if (!t) throw new Error(`Unknown event type: ${e.type}`);

const link = `${$env.LENDLOOP_APP_URL}/loans/${encodeURIComponent(e.loan.id)}`;
const dates = `${formatDate(e.loan.startDate)} – ${formatDate(e.loan.endDate)}`;

return [{
  json: {
    to: e.recipient.email,
    subject: t.subject,
    html: layout({ greetingName: e.recipient.name, line: t.line, detail: [tool, dates], link, cta: t.cta }),
    text: `Hi ${e.recipient.name},\n\n${t.line}\n\n${tool}\n${dates}\n\n${t.cta}: ${link}\n`,
  },
}];

// --- sign: identical in every LendLoop workflow ---
// Same algorithm as signRequest in convex/lib/signature.ts:
//   X-LendLoop-Signature: t=<unix seconds>,v1=HMAC-SHA256(secret, `${t}.${METHOD}.${path}.${body}`)
// The HTTP Request node sends `rawBody` as a raw string, so the signed bytes are the sent bytes.
const crypto = require('crypto');
function sign(method, path, body) {
  const t = Math.floor(Date.now() / 1000);
  const v1 = crypto
    .createHmac('sha256', $env.N8N_TO_CONVEX_SECRET)
    .update(`${t}.${method}.${path}.${body}`, 'utf8')
    .digest('hex');
  const base = $env.LENDLOOP_CONVEX_SITE_URL.replace(/\/$/, '');
  return { url: base + path, signature: `t=${t},v1=${v1}`, rawBody: body };
}
// --- end sign ---

// Tell Convex how the email went. Convex records it once per event (idempotent by eventId).
const { eventId } = $('Verify signature').first().json.event;
const { status } = $input.first().json; // "sent" or "failed", set by the Mark nodes
const body = JSON.stringify({ eventId, status, executionId: $execution.id });
return [{ json: { ...sign('POST', '/automation/notifications/result', body), status } }];
